#include "VBoundMemBlockHarness.h"
#include "VBoundMemBlockHarness___024root.h"
#include "verilated.h"
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>

static void tick(VBoundMemBlockHarness& top) {
  top.clock = 0;
  top.eval();
  top.clock = 1;
  top.eval();
  top.clock = 0;
  top.eval();
}

static std::string hex_value(uint64_t value) {
  std::ostringstream os;
  os << "0x" << std::hex << value;
  return os.str();
}

static bool expect_equal(const char* phase, int cycle, uint64_t seen, uint64_t expected) {
  if (seen == expected) return true;
  std::cerr << phase << " cycle=" << cycle << " expected=" << hex_value(expected)
            << " seen=" << hex_value(seen) << std::endl;
  return false;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Verilated::randReset(0);

  VBoundMemBlockHarness top;
  auto* root = top.rootp;
  const uint64_t kAddr = 0x123456789ULL;

  top.clock = 0;
  top.reset = 1;
  top.io_hartId = 0;
  top.io_redirect_valid = 0;
  top.io_lsqio_exceptionAddr_isStore = 0;
  for (int i = 0; i < 2; ++i) tick(top);
  top.reset = 0;
  top.eval();

  if (top.io_lsqio_exceptionAddr_vaddr == kAddr) {
    std::cerr << "unexpected initial LSQ exception address collision" << std::endl;
    return 10;
  }

  root->BoundMemBlockHarness__DOT__mem__DOT__atomicsExceptionAddress = kAddr;
  root->BoundMemBlockHarness__DOT__mem__DOT__atomicsUnit__DOT__in_src_0 = kAddr;
  root->BoundMemBlockHarness__DOT__mem__DOT__atomicsUnit__DOT__atom_override_xtval = 1;
  top.eval();

  tick(top);

  for (int cycle = 0; cycle < 3; ++cycle) {
    tick(top);
    if (!expect_equal("pre_redirect", cycle, top.io_lsqio_exceptionAddr_vaddr, kAddr)) {
      return 1;
    }
  }

  top.io_redirect_valid = 1;
  tick(top);
  top.io_redirect_valid = 0;

  for (int cycle = 0; cycle < 9; ++cycle) {
    tick(top);
    if (!expect_equal("post_redirect_hold", cycle, top.io_lsqio_exceptionAddr_vaddr, kAddr)) {
      return 2;
    }
  }

  int drop_cycle = -1;
  for (int cycle = 9; cycle < 14; ++cycle) {
    tick(top);
    const uint64_t seen = top.io_lsqio_exceptionAddr_vaddr;
    if (drop_cycle < 0) {
      if (seen != kAddr) {
        drop_cycle = cycle;
      }
    } else if (seen == kAddr) {
      std::cerr << "address reappeared after clear at cycle=" << cycle
                << " seen=" << hex_value(seen) << std::endl;
      return 3;
    }
  }

  if (drop_cycle < 0) {
    std::cerr << "address did not clear after delayed redirect window" << std::endl;
    return 4;
  }

  std::cout << "property holds; drop_cycle=" << drop_cycle << std::endl;
  return 0;
}
EOT

