    bits.elements("data").asInstanceOf[UInt] := 0.U
    if (bits.elements.contains("error")) bits.elements("error").asInstanceOf[Bool] := false.B
    if (bits.elements.contains("data_raw")) bits.elements("data_raw").asInstanceOf[UInt] := 0.U
    if (bits.elements.contains("hasdata")) bits.elements("hasdata").asInstanceOf[Bool] := false.B
    if (bits.elements.contains("refill_done")) bits.elements("refill_done").asInstanceOf[Bool] := false.B
  }

  io.feedbackValid := dut.io.feedbackSlow.valid
  io.feedbackHit := dut.io.feedbackSlow.bits.hit
  io.feedbackSourceType := dut.io.feedbackSlow.bits.sourceType
}

object LoadUnitReplayWrapperMain extends App {
