  std::cout << "commit_uop_total=" << uop_total << "\n";
  std::cout << "commit_instr_total=" << instr_total << "\n";

  delete top;

  if (uop_total != 1) {
    std::cerr << "unexpected commit_uop_total" << std::endl;
    return 2;
  }
  if (instr_total != 1) {
    std::cerr << "unexpected commit_instr_total" << std::endl;
    return 3;
  }
  return 0;
}
EOF

