package xiangshan.backend

import chisel3._
import chisel3.util._
import chipsalliance.rocketchip.config.Parameters
import freechips.rocketchip.diplomacy.LazyModule
import top.{Generator, MinimalConfig, SFC}
import xiangshan._
import xiangshan.backend.exu.ExuConfig
import xiangshan.frontend.BrType

object CtrlBlockRedirectVsetMain {
  def config: Parameters = {
    val base = (new MinimalConfig(1)).alter((site, here, up) => {
      case DebugOptionsKey => up(DebugOptionsKey).copy(
        EnableDifftest = false,
        AlwaysBasicDiff = false,
        EnablePerfDebug = false,
        EnableTopDown = false
      )
    })
    base.alterPartial {
      case XSCoreParamsKey => base(XSTileKey).head
    }
  }

  def dpExuConfigGroups(implicit p: Parameters): Seq[Seq[Seq[ExuConfig]]] = {
    val exu = p(XSCoreParamsKey).exuParameters
    val intLaneCfgs = Seq(AluExeUnitCfg, MulDivExeUnitCfg, JumpCSRExeUnitCfg, LdExeUnitCfg, StaExeUnitCfg, StdExeUnitCfg)
    val vecLaneCfgs = Seq(FmacExeUnitCfg, FmiscExeUnitCfg)

    val intDpPorts = (0 until exu.AluCnt).map { i =>
      if (i < exu.JmpCnt) Seq(0, 1, 2)
      else if (i < 2 * exu.MduCnt) Seq(0, 1)
      else Seq(0)
    }
    val lsDpPorts =
      (0 until exu.LduCnt).map(_ => Seq(3)) ++
      (0 until exu.StuCnt).map(_ => Seq(4)) ++
      (0 until exu.StuCnt).map(_ => Seq(5))
    val fpDpPorts = (0 until exu.FmacCnt).map { i =>
      if (i < 2 * exu.FmiscCnt) Seq(0, 1) else Seq(0)
    }

    val intDispatchPorts = intDpPorts ++ lsDpPorts
    val vecDispatchPorts = fpDpPorts
    val intDpExu = intDispatchPorts.map(_.map(intLaneCfgs(_)))
    val vecDpExu = vecDispatchPorts.map(_.map(vecLaneCfgs(_)))

    Seq(
      intDpExu.take(exu.AluCnt),
      intDpExu.drop(exu.AluCnt),
      vecDpExu
    )
  }

  def main(args: Array[String]): Unit = {
    implicit val p: Parameters = config
    Generator.execute(
      Array("--target-dir", "build/ctrlblock-repro", "-X", "verilog", "--remove-assert"),
      new CtrlBlockRedirectVsetHarness,
      SFC
    )
  }
}

class CtrlBlockRedirectVsetHarness(implicit p: Parameters) extends Module {
  val io = IO(new Bundle {
    val memViolationValid = Input(Bool())
    val cfValid = Input(Bool())
    val cfInstr = Input(UInt(32.W))
    val frontendRedirectValid = Output(Bool())
    val pendingWindow = Output(Bool())
    val wrongPathVsetInDecode = Output(Bool())
    val sawVaddDispatch = Output(Bool())
    val vaddVconfig = Output(UInt(16.W))
  })

  private object DummyWbSource extends HasWritebackSource {
    override val writebackSourceParams: Seq[WritebackSourceParams] = Seq(
      new WritebackSourceParams(Seq(
        Seq(JumpCSRExeUnitCfg),
        Seq(LdExeUnitCfg),
        Seq(LdExeUnitCfg),
        Seq(StaExeUnitCfg),
        Seq(StaExeUnitCfg)
      ))
    )
    override val writebackSourceImp: HasWritebackSourceImp = new HasWritebackSourceImp {}
  }

  private val ctrlBlock = LazyModule(new CtrlBlock(CtrlBlockRedirectVsetMain.dpExuConfigGroups))
  ctrlBlock.addWritebackSink(Seq(DummyWbSource))
  private val dut = Module(ctrlBlock.module)

  dut.io <> WireDefault(0.U.asTypeOf(dut.io))

  dut.io.dispatch.foreach(_.ready := true.B)
  dut.io.rsReady.foreach(_ := true.B)
  dut.io.enqLsq.canAccept := true.B
  dut.io.enqLsq.resp.foreach(_ := 0.U.asTypeOf(dut.io.enqLsq.resp.head))
